"""Literal trialPreparation parent under real desktop media contexts and CSS margin collapse."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines()
defs='\n'.join(x for x in src if x.startswith(('const esc=','const icons=','const icon=','const t=','const btn=','const notice=','function trialPreparation(')))
variants=[('hidden',False,False,'migration_test','trial.example.invalid'),('unprepared',True,False,'migration_test','trial.example.invalid'),('ready',True,True,'migration_test','trial.example.invalid'),('latin',True,True,'tenant_'+'migration_records_v1_'*10,'db-'*24+'example.invalid'),('korean',True,True,'마이그레이션검증시험데이터베이스_'*6,'시험서버-'*20+'example.invalid')]
cases=[dict(id=f'{lang}-{viewport}-{width}-{key}',lang=lang,viewportWidth=viewport,parentWidth=width,selected=selected,ready=ready,dbms='SQL Server',database=db,host=host) for lang in ['ko','en'] for viewport in [1110,1280] for width in [656,904] for key,selected,ready,db,host in variants]
(o/'trialpreparation-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
frame='''<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="http://10.211.55.2:8768/trialpreparation-original.css"><style>.fixture{position:absolute;left:30px;top:30px;display:flow-root}.notice,.prepared-db{animation:none!important}</style><div class="fixture" id="fixture"><div id="trial-preparation"></div></div><script>let lang=CASE.lang,state={selected:new Set(CASE.selected?['trial']:[]),trial:{ready:CASE.ready,db:CASE.database,host:CASE.host},dbms:CASE.dbms};'''+defs+''';document.getElementById('fixture').style.width=CASE.parentWidth+'px';document.getElementById('trial-preparation').innerHTML=trialPreparation();window.fixtureReady=document.fonts.ready;</script>'''
read='''function read(f){const d=f.contentDocument,e=d.getElementById('trial-preparation'),anchor=d.getElementById('fixture').getBoundingClientRect(),rect=e.getBoundingClientRect(),box=x=>{if(!x)return null;const b=x.getBoundingClientRect();return{x:b.x-rect.x,y:b.y-rect.y,width:b.width,height:b.height}},button=e.querySelector('button'),notice=e.querySelector('.notice'),card=e.querySelector('.prepared-db');return{id:f.dataset.id,x:rect.x-anchor.x,y:rect.y-anchor.y,width:rect.width,height:rect.height,notice:box(notice),button:box(button),card:box(card),title:notice?.querySelector('strong').textContent??null,text:notice?.querySelector('p').textContent??null,buttonText:button?.textContent??null,cardText:card?.textContent??null,kind:notice?.className??null,buttonEnabled:button?!button.disabled:null};}'''
script='const cases='+json.dumps(cases,ensure_ascii=False)+';const frame='+json.dumps(frame,ensure_ascii=False).replace('</','<\\/')+''';const ready=[];for(const c of cases){const f=document.createElement('iframe');f.dataset.id=c.id;f.style.width=c.viewportWidth+'px';f.style.height='720px';f.srcdoc=frame.replaceAll('CASE',JSON.stringify(c));ready.push(new Promise(res=>f.onload=async()=>{await f.contentWindow.fixtureReady;res()}));document.getElementById('fixtures').append(f)}'''+read+'''document.getElementById('trialpreparation-record').onclick=async()=>{await Promise.all(ready);const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:[...document.querySelectorAll('iframe')].map(read)})});if(!response.ok)throw Error('Evidence failed');document.getElementById('trialpreparation-record').textContent='TrialPreparation recorded'};'''
(o/'trialpreparation.html').write_text('<!doctype html><meta charset="utf-8"><title>TrialPreparation · original isolation</title><style>iframe{position:absolute;left:0;top:100px;border:0}iframe:not(:first-child){visibility:hidden}#trialpreparation-record{position:fixed;left:30px;top:20px}</style><button id="trialpreparation-record">Record TrialPreparation</button><div id="fixtures"></div><script>'+script+'</script>')
for p in [o/'trialpreparation-cases.json',r/'docs/replica/source/trialpreparation-cases.json']:p.write_text(json.dumps(cases,ensure_ascii=False,indent=2)+'\n')
print(len(cases),'independent desktop parent cases')
